constructor(IVault vault, bytes32 actionIdDisambiguator) Authentication(actionIdDisambiguator) {
        if (address(vault) == address(0)) {
            revert VaultNotSet();
        }

        _vault = vault;
    }

constructor(
        IVault vault,
        string memory factoryVersion,
        uint256 rateProviderVersion
    ) SingletonAuthentication(vault) Version(factoryVersion) {
        _rateProviderVersion = rateProviderVersion;
    }

constructor(uint32 tokenIndex, uint32 pairIndex) {
        uint8 szDecimals = HyperTokenInfoPrecompile.szDecimals(tokenIndex);





        _spotPriceMultiplier = 1e18 / (10 ** (8 - szDecimals));

        _pairIndex = pairIndex;
        _tokenIndex = tokenIndex;
    }

function getRateProvider(
        uint32 tokenIndex,
        uint32 pairIndex
    ) external view returns (IHyperEVMRateProvider rateProvider);

function version() external view returns (string memory) {
        return _version;
    }

function _canPerform(bytes32 actionId, address account, address where) internal view returns (bool) {
        return _vault.getAuthorizer().canPerform(actionId, account, where);
    }

function getAuthorizer() public view returns (IAuthorizer) {
        return getVault().getAuthorizer();
    }

function getRateProviderVersion() external view returns (uint256) {
        return _rateProviderVersion;
    }

function create(uint32 tokenIndex, uint32 pairIndex) external returns (IHyperEVMRateProvider rateProvider) {
        _ensureEnabled();

        bytes32 rateProviderId = _computeRateProviderId(tokenIndex, pairIndex);

        address existingRateProvider = address(_rateProviders[rateProviderId]);

        if (existingRateProvider != address(0)) {
            revert RateProviderAlreadyExists(tokenIndex, pairIndex, existingRateProvider);
        }

        rateProvider = IHyperEVMRateProvider(address(new HyperEVMRateProvider(tokenIndex, pairIndex)));
        _rateProviders[rateProviderId] = rateProvider;
        _isRateProviderFromFactory[rateProvider] = true;

        emit RateProviderCreated(tokenIndex, pairIndex, address(rateProvider));
    }

function getRateProvider(
        uint32 tokenIndex,
        uint32 pairIndex
    ) external view returns (IHyperEVMRateProvider rateProvider) {
        bytes32 rateProviderId = _computeRateProviderId(tokenIndex, pairIndex);
        rateProvider = _rateProviders[rateProviderId];
        if (address(rateProvider) == address(0)) {
            revert RateProviderNotFound(tokenIndex, pairIndex);
        }
        return rateProvider;
    }

function isRateProviderFromFactory(IHyperEVMRateProvider rateProvider) external view returns (bool) {
        return _isRateProviderFromFactory[rateProvider];
    }

function disable() external authenticate {
        _ensureEnabled();

        _isDisabled = true;
        emit RateProviderFactoryDisabled();
    }

function getSpotPriceMultiplier() external view returns (uint256) {
        return _spotPriceMultiplier;
    }

function getTokenIndex() external view returns (uint32) {
        return _tokenIndex;
    }

function getPairIndex() external view returns (uint32) {
        return _pairIndex;
    }

function getRate() external view returns (uint256) {
        uint256 spotPrice = HyperSpotPricePrecompile.spotPrice(_pairIndex);
        return spotPrice * _spotPriceMultiplier;
    }

function registerPool(
        address pool,
        address poolCreator,
        bool protocolFeeExempt
    ) external returns (uint256 aggregateSwapFeePercentage, uint256 aggregateYieldFeePercentage);

function registerPool(
        address pool,
        TokenConfig[] memory tokenConfig,
        uint256 swapFeePercentage,
        uint32 pauseWindowEndTime,
        bool protocolFeeExempt,
        PoolRoleAccounts calldata roleAccounts,
        address poolHooksContract,
        LiquidityManagement calldata liquidityManagement
    ) external;

function collectAggregateFees(
        address pool
    ) external returns (uint256[] memory swapFeeAmounts, uint256[] memory yieldFeeAmounts);

function getActionId(bytes4 selector) public view override returns (bytes32) {



        return keccak256(abi.encodePacked(_actionIdDisambiguator, selector));
    }

function _canPerform(bytes32 actionId, address user) internal view override returns (bool) {
        return _vault.getAuthorizer().canPerform(actionId, user, address(this));
    }
